('M32602','writing',1,62,'fill_char','Пиньинь [jiǎo] — тохирох ханзыг бич: 这瓶饮料三元五___。',null,'角','strict',1,null,null,false,array['sk.writing.fill_char','voc.hsk3','hsk30']::text[],'«三元五角» нь «3 юань 5 мао» гэсэн үнийн хэлбэр. «角 (jiǎo)» нь юаний аравны нэг (мао). Ярианд «毛» гэдэг ч бичигт «角».',null,null,null,'{"key": "角", "keyMn": "Зөв ханз: 角", "why": "«三元五角» нь «3 юань 5 мао» гэсэн үнийн хэлбэр. «角 (jiǎo)» нь юаний аравны нэг (мао). Ярианд «毛» гэдэг ч бичигт «角».", "words": [{"zh": "元", "pinyin": "yuán", "mn": "юань"}, {"zh": "角", "pinyin": "jiǎo", "mn": "мао (1/10 юань)"}, {"zh": "瓶", "pinyin": "píng", "mn": "шил"}, {"zh": "饮料", "pinyin": "yǐn liào", "mn": "ундаа"}], "tip": "Пиньинь болон өгүүлбэрийн утгаас таарах ханзыг ол."}'::jsonb),
('M32602','writing',1,63,'fill_char','Пиньинь [tè] — тохирох ханзыг бич: 我一天没吃饭，现在___别饿。',null,'特','strict',1,null,null,false,array['sk.writing.fill_char','voc.hsk3','hsk30']::text[],'«特别» нь «маш, ялангуяа» гэсэн үгийн дараа «饿» гэсэн тэмдэг нэр орно. «我一天没吃饭» тул «маш өлсөж байна».',null,null,null,'{"key": "特", "keyMn": "Зөв ханз: 特", "why": "«特别» нь «маш, ялангуяа» гэсэн үгийн дараа «饿» гэсэн тэмдэг нэр орно. «我一天没吃饭» тул «маш өлсөж байна».", "words": [{"zh": "特别", "pinyin": "tè bié", "mn": "маш, онцгой"}, {"zh": "饿", "pinyin": "è", "mn": "өлсөх"}, {"zh": "一天", "pinyin": "yī tiān", "mn": "нэг өдөр"}, {"zh": "现在", "pinyin": "xiàn zài", "mn": "одоо"}], "tip": "Пиньинь болон өгүүлбэрийн утгаас таарах ханзыг ол."}'::jsonb),
('M32602','writing',1,64,'fill_char','Пиньинь [hǎi] — тохирох ханзыг бич: 暑假我们全家要去___边玩。',null,'海','strict',1,null,null,false,array['sk.writing.fill_char','voc.hsk3','hsk30']::text[],'«海边» нь «далайн эрэг». Зуны амралтаар гэр бүлээрээ далайн эрэгт зугаалах гэсэн өгүүлбэр.',null,null,null,'{"key": "海", "keyMn": "Зөв ханз: 海", "why": "«海边» нь «далайн эрэг». Зуны амралтаар гэр бүлээрээ далайн эрэгт зугаалах гэсэн өгүүлбэр.", "words": [{"zh": "暑假", "pinyin": "shǔ jià", "mn": "зуны амралт"}, {"zh": "全家", "pinyin": "quán jiā", "mn": "бүх гэр бүл"}, {"zh": "海边", "pinyin": "hǎi biān", "mn": "далайн эрэг"}, {"zh": "玩", "pinyin": "wán", "mn": "тоглох, зугаалах"}], "tip": "Пиньинь болон өгүүлбэрийн утгаас таарах ханзыг ол."}'::jsonb),
('M32602','writing',1,65,'fill_char','Пиньинь [tǐng] — тохирох ханзыг бич: 我发现这条街上饭店___多的。',null,'挺','strict',1,null,null,false,array['sk.writing.fill_char','voc.hsk3','hsk30']::text[],'«挺…的» бүтэц нь «нэлээн, нэлээд» гэсэн утгатай. «饭店挺多的» нь «зоогийн газар нэлээн олон байна».',null,null,null,'{"key": "挺", "keyMn": "Зөв ханз: 挺", "why": "«挺…的» бүтэц нь «нэлээн, нэлээд» гэсэн утгатай. «饭店挺多的» нь «зоогийн газар нэлээн олон байна».", "words": [{"zh": "挺…的", "pinyin": "tǐng … de", "mn": "нэлээн"}, {"zh": "发现", "pinyin": "fā xiàn", "mn": "анзаарах"}, {"zh": "条", "pinyin": "tiáo", "mn": "тоолуур (гудамж)"}, {"zh": "饭店", "pinyin": "fàn diàn", "mn": "зоогийн газар"}], "tip": "Пиньинь болон өгүүлбэрийн утгаас таарах ханзыг ол."}'::jsonb),
('M32602','writing',2,66,'picture_sentence','Зургийг хараад өгөгдсөн үгээр өгүүлбэр зохио: 检票',null,'上火车前要先检票。','manual',1,null,'/mock-tests/m32602/img/q66.webp',true,array['sk.writing.picture_sentence','voc.hsk3','hsk30']::text[],'Зурагт хүмүүс галт тэргэнд сууж ороход шалгуулахаар жагсаж, ажилтан тасалбар шалгаж байна. «检票» (тасалбар шалгах) гэсэн үгийг үйл үг болгон хэрэглэж, юу хийж байгааг энгийнээр бич.',null,null,null,'{"key": "上火车前要先检票。", "keyMn": "Галт тэргэнд суухаасаа өмнө эхлээд тасалбараа шалгуулна", "why": "Зурагт хүмүүс галт тэргэнд сууж ороход шалгуулахаар жагсаж, ажилтан тасалбар шалгаж байна. «检票» (тасалбар шалгах) гэсэн үгийг үйл үг болгон хэрэглэж, юу хийж байгааг энгийнээр бич.", "tip": "Өгөгдсөн үгийг заавал ашигла, зураг дээр харагдаж буй үйлдлийг бич. Оноо авах бүтэц: тайлбар + өгөгдсөн үг + үйл үг, өгүүлбэр 8-12 үсэг.", "words": [{"zh": "检票", "pinyin": "jiǎn piào", "mn": "тасалбар шалгах"}, {"zh": "火车", "pinyin": "huǒ chē", "mn": "галт тэрэг"}, {"zh": "先", "pinyin": "xiān", "mn": "эхлээд"}, {"zh": "要", "pinyin": "yào", "mn": "хэрэгтэй"}]}'::jsonb),
('M32602','writing',2,67,'picture_sentence','Зургийг хараад өгөгдсөн үгээр өгүүлбэр зохио: 假期',null,'假期里，我和朋友去旅游。','manual',1,null,'/mock-tests/m32602/img/q67.webp',true,array['sk.writing.picture_sentence','voc.hsk3','hsk30']::text[],'Зурагт хэдэн залуу уулан дээр хамтдаа зураг дарж байна. «假期» (амралт) гэсэн үгээр «假期里，我和朋友去旅游» гэж бич: цаг + хэн + юу хийх.',null,null,null,'{"key": "假期里，我和朋友去旅游。", "keyMn": "Амралтаараа би найзуудтайгаа аялна", "why": "Зурагт хэдэн залуу уулан дээр хамтдаа зураг дарж байна. «假期» (амралт) гэсэн үгээр «假期里，我和朋友去旅游» гэж бич: цаг + хэн + юу хийх.", "tip": "«…里» цагийн үгийн дараа орж «…дотор» гэсэн утга өгнө.", "words": [{"zh": "假期", "pinyin": "jià qī", "mn": "амралт"}, {"zh": "朋友", "pinyin": "péng yǒu", "mn": "найз"}, {"zh": "旅游", "pinyin": "lǚ yóu", "mn": "аялах"}, {"zh": "照相", "pinyin": "zhào xiàng", "mn": "зураг авах"}]}'::jsonb),
('M32602','writing',2,68,'picture_sentence','Зургийг хараад өгөгдсөн үгээр өгүүлбэр зохио: 信用卡',null,'我办了一张信用卡。','manual',1,null,'/mock-tests/m32602/img/q68.webp',true,array['sk.writing.picture_sentence','voc.hsk3','hsk30']::text[],'Зурагт охин банкны карт харуулж байна. «信用卡» (зээлийн карт) гэсэн үгээр «我办了一张信用卡» гэж бич: «办» нь карт гаргуулах, «一张» нь тоолуур үг.',null,null,null,'{"key": "我办了一张信用卡。", "keyMn": "Би зээлийн карт гаргуулсан", "why": "Зурагт охин банкны карт харуулж байна. «信用卡» (зээлийн карт) гэсэн үгээр «我办了一张信用卡» гэж бич: «办» нь карт гаргуулах, «一张» нь тоолуур үг.", "tip": "Картанд «张» тоолуур үгийг хэрэглэнэ.", "words": [{"zh": "信用卡", "pinyin": "xìn yòng kǎ", "mn": "зээлийн карт"}, {"zh": "办", "pinyin": "bàn", "mn": "хийлгэх, гаргуулах"}, {"zh": "一张", "pinyin": "yī zhāng", "mn": "нэг ширхэг (хуудас, карт)"}, {"zh": "银行", "pinyin": "yín háng", "mn": "банк"}]}'::jsonb),
('M32602','writing',2,69,'picture_sentence','Зургийг хараад өгөгдсөн үгээр өгүүлбэр зохио: 经过',null,'我放学回家的时候会经过一家水果店。','manual',1,null,'/mock-tests/m32602/img/q69.webp',true,array['sk.writing.picture_sentence','voc.hsk3','hsk30']::text[],'Зурагт хүн «水果店» гэсэн зарын өмнө гүйж өнгөрч байна. «经过» (дайрч өнгөрөх) гэсэн үгээр «我放学回家的时候会经过一家水果店» гэж бич: цаг + газар.',null,null,null,'{"key": "我放学回家的时候会经过一家水果店。", "keyMn": "Би сургуулиасаа гэртээ харихдаа нэг жимсний дэлгүүрийн хажуугаар өнгөрдөг", "why": "Зурагт хүн «水果店» гэсэн зарын өмнө гүйж өнгөрч байна. «经过» (дайрч өнгөрөх) гэсэн үгээр «我放学回家的时候会经过一家水果店» гэж бич: цаг + газар.", "tip": "«经过 + газар» гэж бич. «…的时候» нь «…үед».", "words": [{"zh": "经过", "pinyin": "jīng guò", "mn": "дайрч өнгөрөх"}, {"zh": "水果店", "pinyin": "shuǐ guǒ diàn", "mn": "жимсний дэлгүүр"}, {"zh": "放学", "pinyin": "fàng xué", "mn": "хичээл тарах"}, {"zh": "回家", "pinyin": "huí jiā", "mn": "гэртээ харих"}]}'::jsonb),
('M32602','writing',2,70,'picture_sentence','Зургийг хараад өгөгдсөн үгээр өгүүлбэр зохио: 干净',null,'房间里打扫得很干净。','manual',1,null,'/mock-tests/m32602/img/q70.webp',true,array['sk.writing.picture_sentence','voc.hsk3','hsk30']::text[],'Зурагт цэвэрхэн өрөө, ширээн дээр ном, компьютер байна. «干净» (цэвэрхэн) гэсэн үгээр «房间里打扫得很干净» гэж бич: «V得很 + тэмдэг нэр» бүтэц.',null,null,null,'{"key": "房间里打扫得很干净。", "keyMn": "Өрөөг маш цэвэрхэн цэвэрлэсэн", "why": "Зурагт цэвэрхэн өрөө, ширээн дээр ном, компьютер байна. «干净» (цэвэрхэн) гэсэн үгээр «房间里打扫得很干净» гэж бич: «V得很 + тэмдэг нэр» бүтэц.", "tip": "«V + 得 + 很 + тэмдэг нэр» нь үйлдлийн түвшинг тайлбарладаг.", "words": [{"zh": "干净", "pinyin": "gān jìng", "mn": "цэвэрхэн"}, {"zh": "房间", "pinyin": "fáng jiān", "mn": "өрөө"}, {"zh": "打扫", "pinyin": "dǎ sǎo", "mn": "цэвэрлэх"}, {"zh": "得", "pinyin": "dé", "mn": "(үйлийн түвшин заана)"}]}'::jsonb);
